<script setup lang="ts">
import { computed, ref } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'

const voiceStore = useVoiceStore()
const entries = computed(() => voiceStore.connectionDiagnostics)
const copied = ref(false)

async function copyDiagnostics() {
  const report = entries.value.join('\n')
  try {
    await navigator.clipboard.writeText(report)
  } catch {
    const field = document.createElement('textarea')
    field.value = report
    document.body.appendChild(field)
    field.select()
    document.execCommand('copy')
    field.remove()
  }
  copied.value = true
  window.setTimeout(() => { copied.value = false }, 1500)
}
</script>

<template>
  <details v-if="entries.length" class="diagnostics">
    <summary>Verbindungsdiagnose anzeigen</summary>
    <p>Der Bericht enthält WebRTC-Zustände, aber keine IP-Adressen oder Audiodaten.</p>
    <button type="button" @click="copyDiagnostics">
      {{ copied ? 'Kopiert – hier einfügen' : 'Diagnose kopieren' }}
    </button>
    <pre>{{ entries.join('\n') }}</pre>
  </details>
</template>

<style scoped>
.diagnostics { margin-top: 1rem; color: #ddd; font-size: 0.85rem; }
.diagnostics summary { cursor: pointer; }
.diagnostics p { color: #aaa; }
.diagnostics button { padding: 0.5rem 0.75rem; cursor: pointer; }
.diagnostics pre {
  max-height: 16rem;
  overflow: auto;
  padding: 0.75rem;
  background: #09090b;
  border-radius: 6px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
</style>
